def bpm(u, match, seen, n, graph):
	for j in range(n):
		if graph[u][j] == 1 and seen[j] == False:
			seen[j] = True
			if match[j] == -1 or bpm(match[j], match, seen, n, graph):
				match[j] = u
				return True
	return False

def solve():
	(n, k) = [int(i) for i in input().split()]
	valid_points = [[1 for i in range(n)] for j in range(n)]
	for i in range(n):
		valid_points[i][i] = 0
	for i in range(k):
		perm = [int(d) - 1 for d in input().split()]
		for j in range(1, n):
			for r in range(j - 1, -1, -1):
				valid_points[perm[j]][perm[r]] = 0
	result = 0
	match = [-1] * n
	for i in range(n):
		seen = [False] * n
		if bpm(i, match, seen, n, valid_points):
			result += 1
	print(n - result)
	final_ans = [0] * n
	for i in range(n):
		if match[i] != -1:
			final_ans[match[i]] = i + 1
	for i in final_ans:
		print(i, end=' ')
	print()
t = int(input())
while t > 0:
	solve()
	t -= 1
